"""SSE passthrough with the upstream hidden.

Events are forwarded as they arrive. Only events that name the upstream model
or carry an upstream error message are rewritten; every other event keeps its
fields as upstream sent them (line endings are normalised to \\n).
"""
import json
from typing import AsyncIterator, Dict, List

STREAM_ERROR_MESSAGE = 'The model service failed while answering.'


class EventRewriter:
    """Rewrites one stream's events for the client and collects token usage."""

    def __init__(self, fmt: str, alias_id: str):
        self.fmt = fmt
        self.alias_id = alias_id
        self.usage: Dict[str, int] = {}

    def rewrite(self, lines: List[str]) -> bytes:
        data_lines = [line[5:].removeprefix(' ') for line in lines if line.startswith('data:')]
        if data_lines:
            try:
                data = json.loads('\n'.join(data_lines))
            except json.JSONDecodeError:
                data = None
            if isinstance(data, dict) and self._rewrite(data):
                kept = [line for line in lines if not line.startswith('data:')]
                lines = kept + ['data: ' + json.dumps(data, ensure_ascii=False, separators=(',', ':'))]
        return ('\n'.join(lines) + '\n\n').encode()

    def _rewrite(self, data: dict) -> bool:
        """Edits data in place; True when anything changed."""
        if self.fmt == 'anthropic':
            return self._rewrite_anthropic(data)
        return self._rewrite_responses(data)

    def _rewrite_anthropic(self, data: dict) -> bool:
        kind = data.get('type')
        if kind == 'message_start' and isinstance(data.get('message'), dict):
            message = data['message']
            self._add_usage(message.get('usage'))
            if 'model' in message:
                message['model'] = self.alias_id
                return True
        elif kind == 'message_delta':
            self._add_usage(data.get('usage'))
        elif kind == 'error':
            error = data.get('error') if isinstance(data.get('error'), dict) else {}
            data['error'] = {'type': error.get('type', 'api_error'), 'message': STREAM_ERROR_MESSAGE}
            return True
        return False

    def _rewrite_responses(self, data: dict) -> bool:
        kind = data.get('type')
        changed = False
        response = data.get('response')
        if isinstance(response, dict):
            # Every response.* lifecycle event (created, in_progress, completed,
            # incomplete, failed) carries the whole response object, model included.
            if 'model' in response:
                response['model'] = self.alias_id
                changed = True
            if kind == 'response.completed':
                self._add_usage(response.get('usage'))
            if isinstance(response.get('error'), dict):
                response['error'] = {'code': response['error'].get('code'), 'message': STREAM_ERROR_MESSAGE}
                changed = True
        if kind == 'error':
            data['message'] = STREAM_ERROR_MESSAGE
            data.pop('param', None)
            changed = True
        return changed

    def _add_usage(self, usage):
