@csrf_exempt
def cb_webhook(request):
    SUBSCRIPTION_EVENTS = ['subscription_created', 'subscription_started', 'subscription_activated', 'subscription_changed', 'subscription_cancellation_scheduled', 'subscription_cancelled', 'subscription_reactivated', 'subscription_renewed',]

    payload = request.body
    cb_event = json.loads(payload)

    if cb_event['event_type'] in SUBSCRIPTION_EVENTS:
        cb_sub = cb_event['content']['subscription']

        # Handle pro subscriptions
        if cb_sub['plan_id'].startswith('pro-'):
            try:
                user = Subscription.objects.get(external_id=cb_event['content']['subscription']['id']).user # in case user is using different email in chargebee
            except:
                user = User.objects.get(email__iexact=cb_event['content']['customer']['email'])
            upsert_subscription(cb_sub, user)

        # Handle JusPrin subscriptions
        elif is_jusprin_subscription(cb_sub['plan_id']):
            return handle_jusprin_webhook(cb_event)
        else:
            return  HttpResponse('')

    if cb_event['event_type'] == 'invoice_generated':
        cb_invoice = cb_event['content']['invoice']
        result = chargebee.Subscription.retrieve(cb_invoice['subscription_id'])
        if result.subscription.plan_id == 'pre-paid-detective-hour-pack':
            try:
                user = PrepaidDHPackPlaceholder.objects.get(external_id=result.subscription.id).user # in case user is using different email in chargebee
            except:
                user = User.objects.get(email__iexact=result.customer.email)
            recharge_prepaid_dh_pack(cb_invoice, user)

    return HttpResponse('')

