    elif cb_subscription.get('status') == 'non_renewing':
        return # subscription watiting to expire. Nothing should be done (or should it?)
    elif cb_subscription.get('status') == 'active':
        sub.expired_at = None
        prorated_reversal_if_needed(sub, cb_subscription, user)  # prorated reversal has to go before subscription is updated, to use the original sub's resource_version
        update_subscription_from_cb_subcription(sub, cb_subscription)
        credit_for_pro_current_term(cb_subscription, user)
        credit_for_dhpack_current_term(cb_subscription, user)
    else:
        raise Exception('Unexpected subscription status: {}'.format(cb_subscription))

    sub.update_pro_status_on_user()

def update_subscription_from_cb_subcription(sub, cb_subscription):
    sub.external_id=cb_subscription['id']
    sub.external_user_id=cb_subscription['customer_id']
    sub.plan_id = cb_subscription['plan_id']
    sub.printers_subscribed = sum([a['quantity'] for a in cb_subscription.get('addons', []) if 'additional-printers' in a['id']]) + 1
    sub.external_resource_version = str(cb_subscription['resource_version'])
    sub.current_term_start = cb_subscription['current_term_start']
    sub.current_term_end = cb_subscription['current_term_end']
    sub.unlimited_dh = has_unlimited_sns_pack(cb_subscription)
    sub.save()

def has_unlimited_sns_pack(subscription):
    for addon in subscription.get('addons', []):
        if addon['id'].startswith('unlimited-dh'):
            return True

    return False

