    PrepaidDHPackPlaceholder.objects.get_or_create(
        user=user,
        defaults={'external_id': invoice['subscription_id'], 'external_user_id': invoice['customer_id']}
    )
    credit_for_invoiced_prepaid_dh_pack(invoice, user)

